4edbc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}},{&amp;quot;di-id&amp;quot;:&amp;quot;dropdownItem.fjhzatmsr8p9&amp;quot;,&amp;quot;di-v&amp;quot;:&amp;quot;Hour&amp;quot;,&amp;quot;di-dv&amp;quot;:&amp;quot;Hour&amp;quot;,&amp;quot;di-ts&amp;quot;:{&amp;quot;ts_bd&amp;quot;:false,&amp;quot;ts_fs&amp;quot;:11,&amp;quot;ts_ff&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;ts_it&amp;quot;:false,&amp;quot;ts_sc&amp;quot;:false,&amp;quot;ts_st&amp;quot;:false,&amp;quot;ts_tw&amp;quot;:400,&amp;quot;ts_un&amp;quot;:false,&amp;quot;ts_va&amp;quot;:&amp;quot;nor&amp;quot;,&amp;quot;ts_bgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#c6dbe1&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#215a6c&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}}]}},&amp;quot;ddefe-t&amp;quot;:&amp;quot;SELECT STATUS&amp;quot;,&amp;quot;type&amp;quot;:&amp;quot;dropdown&amp;quot;}&quot;&gt;Year&lt;/span&gt;. Aurora’s pay ranges are determined by role, level, and location. Within the range, the successful candidate’s starting base pay will be determined based on factors including job-related skills, experience, qualifications, relevant education or training, and market conditions. These ranges may be modified in the future. The successful candidate will also be eligible for an annual bonus, equity compensation, and benefits.&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&amp;nbsp;#LI-td-1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;#Mid-Senior&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Working at Aurora&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;At Aurora, we bring together extraordinarily talented and experienced people united by the strength of our values. We operate with integrity, set outrageous goals, and build a culture where we win together — all without any jerks.&lt;/p&gt;
&lt;p&gt;We believe in-person work increases collaboration, empathy and our ability to lead effectively. As a result, we operate in a hybrid work environment where Aurorans are in office at least 3 days per week.&lt;/p&gt;
&lt;p&gt;Our&lt;a href=&quot;https://aurora.tech/careers&quot;&gt; Careers page&lt;/a&gt; provides insight into what it is like to work at Aurora, and you can find all the latest updates in our &lt;a href=&quot;https://aurora.tech/newsroom&quot;&gt;Newsroom&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to safety&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At the core of everything we do is our commitment to safety. Building best-in-class self-driving technology will take time, and we believe that each employee at Aurora has a role in contributing to safety, every step of the way. Aurora expects commitment to our safety policies from every employee, and seeks candidates who take an active responsibility, can contribute to building an atmosphere of trust, and invest in the organization’s long-term success by prioritizing working safely, no matter what.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Aurora considers candidates without regard to their race, color, religion, national origin, age, sex, gender, gender identity, gender expression, sexual orientation, marital status, pregnancy status, parent or caregiver status, ancestry, political affiliation, veteran and/or military status, physical or mental disability, or any other status protected by federal or state law. Aurora considers qualified applicants with criminal histories, consistent with applicable federal, state, and local law. We are also committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at &lt;a href=&quot;mailto:careersiteaccommodations@aurora.tech&quot;&gt;careersiteaccommodations@aurora.tech&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;For California applicants, information collected and processed as part of your application and any job applications you choose to submit is subject to Aurora’s California Employment Privacy Policy.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Here at Scout Motors, we&#39;re carrying forward the heritage of one of the most iconic American vehicles in history. A vehicle dating back to 1960. One that forged the path for future generations of rugged SUVs and trucks and will do so once again.&lt;/p&gt;
&lt;p&gt;But Scout is more than just a brand, it’s a legacy steeped in a culture of exploration, caretaking, and hard work.&lt;/p&gt;
&lt;p&gt;The Scout brand is all about respect. Respect for the past and the future by taking an iconic American brand that hasn’t been around for a while, electrifying it, digitizing it, and loading it with American innovation. Respect for communities by creating a company that stands for its people and its customers. Respect for both work and play, with vehicles that are equally at home at a camp site, a job site, or on a Tuesday commute. And respect for our customers by developing two powertrains that meet their requirements — an all-electric powertrain as well as the Harvester™ range extender powertrain which includes a built-in gas-powered generator with an estimated 500 miles of combined range.&lt;/p&gt;
&lt;p&gt;At Scout Motors, we empower our talented, inclusive, and entrepreneurial teams to innovate. What makes a Scout employee? Someone who is a visionary and a leader, who seeks new paths and shares lessons learned. A knowledgeable doer who collaborates across the company to build better. A go-getter with unrivaled passion.&lt;/p&gt;
&lt;p&gt;Join us at Scout Motors and be part of shaping the future of transportation. If you&#39;re ready to drive change and make history, apply now!&lt;/p&gt;&lt;/div&gt;&lt;h4&gt;What you’ll do&lt;/h4&gt;
&lt;p&gt;Become part of an iconic brand that is set to revolutionize the electric pick-up truck &amp;amp; rugged SUV marketplace by achieving the following:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Act as the first point of contact for PH Commissioning Team, Production, and Quality to give status updates about current Software releases and ensure smooth software transitions in the assembly line.&lt;/li&gt;
&lt;li&gt;Develop and maintain documentation for release procedures, change management, and issue resolution.&lt;/li&gt;
&lt;li&gt;Coordinate software package releases for trial purposes in the lab and/or production processes incl. over the air updates together with Pilot Hall Commissioning Team, Pilot Hall Validation Team and other stakeholders.&lt;/li&gt;
&lt;li&gt;Pretest software updates on Testbenches and LabCars to confirm efficiency before trialing inside the Assembly Line.&lt;/li&gt;
&lt;li&gt;Validate software deployment to ensure accuracy and prevent errors in the assembly process. Line trial of vehicle data packages and sub tasks.&lt;/li&gt;
&lt;li&gt;Integrate feedback from verification and validation teams to determine optimal implementation timing in final assembly.&lt;/li&gt;
&lt;li&gt;Monitor software deployment to ensure accuracy and prevent errors in the assembly process. Frequently monitor the daily results from the Production Line.&lt;/li&gt;
&lt;li&gt;Reserve and block vehicles for line trials.&lt;/li&gt;
&lt;li&gt;Write deviations of requests and escalation papers when required.&lt;/li&gt;
&lt;li&gt;Support root cause analysis and corrective actions for any software-related assembly issues.&lt;/li&gt;
&lt;li&gt;Create and maintain a way of presenting to other departments a log of current, past, and future software packages.&lt;/li&gt;
&lt;li&gt;Provide regular reports.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location &amp;amp; Travel Expectations&lt;/strong&gt;:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;This role will be based out of the Scout Motors location in Columbia, South Carolina.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;The responsibilities of this role require daily attendance in office with in-person meetings and events regularly.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Applicants should expect that the role will require the ability to convene with Scout colleagues in person and travel to participate in events on behalf of the company from time to time.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;What you’ll bring&amp;nbsp;&lt;/h4&gt;
&lt;p&gt;We expect all Scout employees to have integrity, curiosity, resourcefulness, and strive to exhibit a positive attitude, as well as a growth mindset. You’ll be comfortable with change and flexible in a fast-paced, high-growth environment. You’ll take a collaborative approach to achieve ambitious goals. Here&#39;s what else you&#39;ll bring:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Associate degree in automotive technology, electrical, software engineering or equivalent combination of education and/or experience.&lt;/li&gt;
&lt;li&gt;Minimum 3+ years professional experience with expertise in automotive manufacturing, or automotive engineering.&lt;/li&gt;
&lt;li&gt;Knowledge of software release processes.&lt;/li&gt;
&lt;li&gt;Strong communication skills.&lt;/li&gt;
&lt;li&gt;High analytical skills in resolving data and process inconsistencies across linked systems.&lt;/li&gt;
&lt;li&gt;Skills with navigating organizations and cross-functional collaboration.&lt;/li&gt;
&lt;li&gt;Developing and promoting effective stakeholder relationships.&lt;/li&gt;
&lt;li&gt;Demonstrates personal accountability and follow-through.&lt;/li&gt;
&lt;li&gt;Proficient in creating reports.&lt;/li&gt;
&lt;li&gt;Ability to work independently and in a structured manner, displaying a high level of commitment, effective communication and teamwork skills.&lt;/li&gt;
&lt;li&gt;Able to lift up to 50 lbs. and stand for 4 hours.&lt;/li&gt;
&lt;li&gt;Minimum of High School Diploma, GED or equivalent required for all roles at Scout Motors, Inc.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;What you&#39;ll gain&lt;/h4&gt;
&lt;p&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;The benefits of joining Scout include the chance to build products and a company from the ground up&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;.&amp;nbsp; &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;This is a chance to create something new and lasting – with an iconic brand at its &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;foundation&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;.&amp;nbsp; &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;In addition, Scout &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt;provides&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW27664814 BCX8&quot;&gt; competitive compensation and benefits to support your physical, mental, and financial wellbeing. Program specifics are detailed in company policies and employee benefit guides, select highlights:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Competitive insurance including:
&lt;ul&gt;
&lt;li&gt;Medical, dental, vision and income protection plans&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;401(k) program with:
&lt;ul&gt;
&lt;li&gt;An employer match and immediate vesting&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;Generous Paid Time Off including:
&lt;ul&gt;
&lt;li&gt;20 days planned PTO, as accrued&lt;/li&gt;
&lt;li&gt;40 hours of unplanned PTO and 14 company or floating holidays, annually&lt;/li&gt;
&lt;li&gt;Up to 16 weeks of paid parental leave for biological and adoptive parents of all genders&lt;/li&gt;
&lt;li&gt;Paid leave for circumstances related to bereavement, jury duty, voting time, or military leave&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;Pay Transparency&lt;/h4&gt;
&lt;p&gt;This is a full-time, exempt position eligible to receive a base salary and to participate in an annual performance bonus program. Final salary offered will be determined based on factors including but not limited to the candidate&#39;s skills and experience. The annual performance bonus program is preset and not candidate dependent.&lt;/p&gt;
&lt;p&gt;Initial base salary range = $100,000.00 - $125,000.00&lt;/p&gt;
&lt;p&gt;Internal leveling code: IC9&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Notice to applicants:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;To be considered for career opportunities at Scout Motors, applicants must be 18 years of age or older.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Residing in &lt;strong&gt;San Francisco&lt;/strong&gt;:&amp;nbsp;&lt;em&gt;Pursuant to the San Francisco Fair Chance Ordinance, Scout Motors will consider for employment qualified applicants with arrest and conviction records.&amp;nbsp;&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;Residing in&amp;nbsp;&lt;strong&gt;Los Angeles&lt;/strong&gt;:&amp;nbsp;&lt;em&gt;Scout Motors will consider for employment qualified applicants with criminal histories in a manner consistent with the Los Angeles Fair Chance Initiative for Hiring Ordinance.&amp;nbsp;&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;Residing in&amp;nbsp;&lt;strong&gt;New York City&lt;/strong&gt;:&amp;nbsp;&lt;em&gt;This role is not eligible for remote work in New York City.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;Equal Opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun Highlight SCXW87322304 BCX8&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;Scout Motors is committed to employing a diverse workforce &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW87322304 BCX8&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW87322304 BCX8&quot;&gt;and is proud to be an Equal Opportunity Employer&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW87322304 BCX8&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;Qualified applicants will receive consideration without regard to race, color, religion, sex, national origin, age, sexual orientation, gender identity, gender expression, veteran status, disability, pregnancy,&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW87322304 BCX8&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;or any&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW87322304 BCX8&quot;&gt;other characteristics&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;protected by law.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW87322304 BCX8&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW87322304 BCX8&quot;&gt;Scout Motors is committed to compliance with all&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;ap&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;p&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;licable&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;&amp;nbsp;fair&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;employment&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;p&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;ractice laws&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87322304 BCX8&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW87322304 BCX8&quot;&gt;&amp;nbsp;If you require reasonable accommodation to complete a job application, pre-employment testing, or a job interview or to otherwise participate in the hiring process, please contact ScoutAccommodations@scoutmotors.com.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Anduril Industries is a defense technology company with a mission to transform U.S. and allied military capabilities with advanced technology. By bringing the expertise, technology, and business model of the 21st century’s most innovative companies to the defense industry, Anduril is changing how military systems are designed, built and sold. Anduril’s family of systems is powered by Lattice OS, an AI-powered operating system that turns thousands of data streams into a realtime, 3D command and control center. As the world enters an era of strategic competition, Anduril is committed to bringing cutting-edge autonomy, AI, computer vision, sensor fusion, and networking technology to the military in months, not years.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;ABOUT THE TEAM&lt;/h3&gt;
&lt;p&gt;Anduril&#39;s Space team is dedicated to expanding our AI-powered capabilities into the final frontier, enhancing Space Domain Awareness, Space Control, and Command and Control for U.S. military and allied partners. We&#39;re developing fully integrated hardware and software systems, including Lattice for Space Missions and modular payloads, to address growing threats in space and ensure our Guardians maintain a decisive advantage in this contested warfighting domain.&lt;/p&gt;
&lt;h3&gt;ABOUT THE JOB&lt;/h3&gt;
&lt;p&gt;As an Orbital Software Engineer on Space, you will contribute to the architecture and deployment of software solutions that support specific customer missions for on-orbit spacecraft operations and mission management. As a software engineer, you will provide guidance and oversight to a team developing modular capabilities to support the DoD and IC customers across the space domain. This will involve architecture of an orbital software system in coordination with the Anduril Lattice software platform team, algorithms, techniques and coding development to support orbital systems and their interfacing with multi-domain systems. The Anduril orbital software capability development will ensure integration with legacy systems that have been part of our nation’s critical defense for decades as well as new space systems being added to the cache of orbital and ground-based capabilities. The role will also be responsible for the interfaces to multi-modal payload platforms, bus platforms and networking solutions in proliferated satellite constellations&lt;br&gt;&lt;br&gt;We work with mission partners and operators to deploy reliable and robust capabilities on operationally-relevant fielding timelines to meet complex challenges across the DOD and IC.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;WHAT YOU’LL DO&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Contribute to software solutions that are deployed to customers.&lt;/li&gt;
&lt;li&gt;Contribute to development of on-orbit software capabilities to enable delivery of end-to-end mission systems.&lt;/li&gt;
&lt;li&gt;Integrate with legacy systems to unlock 21st-century capabilities.&lt;/li&gt;
&lt;li&gt;Write code to improve products and scale the mission capability to different users and customers.&lt;/li&gt;
&lt;li&gt;Collaborate across multiple teams to plan, build, and test complex functionality.&lt;/li&gt;
&lt;li&gt;Create and analyze metrics that are leveraged for debugging and monitoring.&lt;/li&gt;
&lt;li&gt;Triage issues, root cause failures, and coordinate next-steps.&lt;/li&gt;
&lt;li&gt;Partner with end-users to turn needs into features while balancing user experience with engineering constraints.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;REQUIRED QUALIFICATIONS&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Strong engineering background from industry or school, ideally in areas/fields such as Computer Science, Software Engineering, Mathematics, or Physics.&lt;/li&gt;
&lt;li&gt;Ability to quickly understand and navigate complex systems and detailed requirements.&lt;/li&gt;
&lt;li&gt;Capable of solving complex technical problems with little oversight.&lt;/li&gt;
&lt;li&gt;Clear communication and organizational skills including documentation and training material.&lt;/li&gt;
&lt;li&gt;Ideally 3+ years professional experience working with a variety of programming languages such as Python, C++, Rust, or Go&lt;/li&gt;
&lt;li&gt;Experience with spacecraft software systems and spacecraft operations.&lt;/li&gt;
&lt;li&gt;Experience with satellite mission autonomy to include fault isolation and recovery systems.&lt;/li&gt;
&lt;li&gt;Eligible to obtain and maintain an active U.S. Secret security clearance.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;PREFERRED QUALIFICATIONS&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Advanced expertise with Python, Go, Rust, or C++.&lt;/li&gt;
&lt;li&gt;Experience with deployment tooling like Kubernetes, OpenShift, or Helm.&lt;/li&gt;
&lt;li&gt;A desire to work on critical software in the space domain.&lt;/li&gt;
&lt;li&gt;Experience with OMS/UCI standards and modular software services development.&lt;/li&gt;
&lt;/ul&gt;
